-- Assessment only: execute solely against authorized S2 qxhhlprentrufobpcgna.
-- No row identities/ciphertexts are returned. No DDL, DML, restore or export.
begin read only; set local statement_timeout='10s'; select jsonb_build_object('buyers', (select jsonb_build_object('total',count(*),'marked_synthetic',count(*) filter(where synthetic is true),'not_marked_synthetic',count(*) filter(where synthetic is not true),'identity_nonempty',count(*) filter(where nullif(identity_ciphertext,'') is not null),'identity_three_part_shape',count(*) filter(where array_length(string_to_array(identity_ciphertext,'.'),1)=3),'source_nonempty',count(*) filter(where nullif(source_ciphertext,'') is not null),'source_three_part_shape',count(*) filter(where nullif(source_ciphertext,'') is not null and array_length(string_to_array(source_ciphertext,'.'),1)=3),'hash_present',count(*) filter(where identity_hash~'^[a-f0-9]{64}$'),'distinct_hashes',count(distinct identity_hash),'preservation_fingerprint_md5',md5(string_agg(md5(id::text||identity_ciphertext||identity_hash||coalesce(source_ciphertext,'')),'' order by id))) from public.bm_buyers), 'foreign_keys', (select coalesce(jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'definition',pg_get_constraintdef(oid)) order by conrelid::regclass::text), '[]'::jsonb) from pg_constraint where contype='f' and confrelid='public.bm_buyers'::regclass), 'self_service_tables_present',(select count(*) from information_schema.tables where table_schema='public' and table_name in ('bm_buyer_accounts','bm_buyer_account_events','bm_buyer_proofs','bm_buyer_proof_uploads','bm_buyer_proof_reviews')),'related_counts',jsonb_build_object('exposures',(select count(*) from public.bm_exposures),'response_tokens',(select count(*) from public.bm_response_tokens),'intake_submissions',(select count(*) from public.buyer_portal_submissions))) as assessment; rollback;

begin read only; set local statement_timeout='10s'; select jsonb_build_object('by_hash_format',(select jsonb_agg(x) from (select (identity_hash~'^[a-f0-9]{64}$') as expected_hmac_hex, count(*) as rows, count(*) filter(where split_part(identity_ciphertext,'.',1)~'^[A-Za-z0-9+/]{16}$' and split_part(identity_ciphertext,'.',3)~'^[A-Za-z0-9+/]{22}==$') as expected_iv_tag_shape,min(length(identity_hash)) as min_hash_length,max(length(identity_hash)) as max_hash_length,count(*) filter(where nullif(source_ciphertext,'') is not null) as source_ciphertext_present from public.bm_buyers group by 1 order by 1) x),'exposures_on_nonstandard_hashes',(select count(*) from public.bm_exposures e join public.bm_buyers b on b.id=e.buyer_id where b.identity_hash !~ '^[a-f0-9]{64}$'),'dependent_relation_counts',jsonb_build_object('duplicate_reviews',(select count(*) from public.bm_duplicate_reviews),'merged_buyer_links',(select count(*) from public.bm_buyers where merged_into is not null))) as shape_assessment; rollback;
